/*
 * hrep_certs.c -- lookup certificates for the formula-representation engine.
 *
 * A certificate states F(a0; b0; w) = f0 at one origin (Roach '96 sec. 14-16).
 * Because the module is generated by the companion basis of f0, the
 * certificate also covers the whole lattice a0 + Z^p, b0 + Z^q that a
 * proper walk can reach. A family certificate (parameters linear in Hrep`al)
 * covers a one-parameter family of such lattices.
 *
 * Every entry is a classical identity (DLMF chapters 13, 15, 16;
 * Prudnikov-Brychkov-Marichev vol. 3 sec. 7). Each is checked against the
 * defining series in tests/test_hrep_certificates.c.
 *
 * Order matters only for ties: a static entry is listed before the family
 * that also contains it, and the walk-length sort is stable for equal
 * distances in this order.
 */

#include "hrep_internal.h"
#include <stddef.h>

#define W  "Hrep`w"
#define AL "Hrep`al"
#define BE "Hrep`be"

static const HrCert CERTS[] = {
    /* ---- 0F0, 1F0 ------------------------------------------------- */
    { 0, 0, { 0 }, { 0 }, "E^" W, NULL, 0 },
    { 1, 0, { AL }, { 0 }, "(1 - " W ")^(-" AL ")", NULL, 1 },

    /* ---- 0F1 ------------------------------------------------------- */
    { 0, 1, { 0 }, { "1/2" }, "Cosh[2 Sqrt[" W "]]", NULL, 0 },
    { 0, 1, { 0 }, { "3/2" }, "Sinh[2 Sqrt[" W "]]/(2 Sqrt[" W "])", NULL, 0 },
    { 0, 1, { 0 }, { AL },
      "Gamma[" AL "] Hrep`I[" AL " - 1, " W "]",
      NULL, 1 },

    /* ---- 1F1 ------------------------------------------------------- */
    { 1, 1, { "1/2" }, { "3/2" }, "Sqrt[Pi] Erfi[Sqrt[" W "]]/(2 Sqrt[" W "])", NULL, 0 },
    { 1, 1, { "1" }, { "2" }, "(E^" W " - 1)/" W, NULL, 0 },
    /* 1F1(a; a+1; w) = a (-w)^-a gamma(a, -w) */
    { 1, 1, { AL }, { AL " + 1" },
      AL " (-" W ")^(-" AL ") (Gamma[" AL "] - Gamma[" AL ", -" W "])",
      "!(IntegerQ[" AL "] && " AL " <= 0)", 1 },
    /* 1F1(1; b; w) = (b-1) e^w w^(1-b) gamma(b-1, w) */
    { 1, 1, { "1" }, { AL },
      "(" AL " - 1) E^" W " " W "^(1 - " AL ") (Gamma[" AL " - 1] - Gamma[" AL " - 1, " W "])",
      "!(IntegerQ[" AL "] && " AL " <= 1)", 1 },
    /* 1F1(a; 2a; w) = Gamma(a+1/2) e^(w/2) (w/4)^(1/2-a) I_(a-1/2)(w/2) */
    { 1, 1, { AL }, { "2 " AL },
      "Gamma[" AL " + 1/2] E^(" W "/2) (" W "/4)^(1/2 - " AL ") BesselI[" AL " - 1/2, " W "/2]",
      "!(IntegerQ[2 " AL "] && " AL " <= 0)", 1 },

    /* ---- 2F1 ------------------------------------------------------- */
    { 2, 1, { "1", "1" }, { "2" }, "-Log[1 - " W "]/" W, NULL, 0 },
    { 2, 1, { "1", "1" }, { "3/2" },
      "ArcSin[Sqrt[" W "]]/(Sqrt[" W "] Sqrt[1 - " W "])", NULL, 0 },
    { 2, 1, { "1/2", "1/2" }, { "3/2" }, "ArcSin[Sqrt[" W "]]/Sqrt[" W "]", NULL, 0 },
    { 2, 1, { "1/2", "1" }, { "3/2" }, "ArcTanh[Sqrt[" W "]]/Sqrt[" W "]", NULL, 0 },
    { 2, 1, { "1/2", "1/2" }, { "1" }, "2 EllipticK[" W "]/Pi", NULL, 0 },
    { 2, 1, { "-1/2", "1/2" }, { "1" }, "2 EllipticE[" W "]/Pi", NULL, 0 },
    /* 2F1(a, a+1/2; 1/2; w) = ((1+sqrt w)^-2a + (1-sqrt w)^-2a)/2 */
    { 2, 1, { AL, AL " + 1/2" }, { "1/2" },
      "((1 + Sqrt[" W "])^(-2 " AL ") + (1 - Sqrt[" W "])^(-2 " AL "))/2", NULL, 1 },
    /* 2F1(a, a+1/2; 3/2; w) = ((1+s)^(1-2a) - (1-s)^(1-2a))/(2 s (1-2a)) */
    { 2, 1, { AL, AL " + 1/2" }, { "3/2" },
      "((1 + Sqrt[" W "])^(1 - 2 " AL ") - (1 - Sqrt[" W "])^(1 - 2 " AL "))"
      "/(2 Sqrt[" W "] (1 - 2 " AL "))",
      AL " != 1/2", 1 },
    /* 2F1(a, -a; 1/2; w) = cos(2 a arcsin sqrt w) */
    { 2, 1, { AL, "-" AL }, { "1/2" },
      "Cos[2 " AL " ArcSin[Sqrt[" W "]]]", NULL, 1 },
    /* 2F1(a, 1-a; 3/2; w) = sin((2a-1) arcsin sqrt w)/((2a-1) sqrt w) */
    { 2, 1, { AL, "1 - " AL }, { "3/2" },
      "Sin[(2 " AL " - 1) ArcSin[Sqrt[" W "]]]/((2 " AL " - 1) Sqrt[" W "])",
      AL " != 1/2", 1 },
    /* 2F1(1, a; 2; w) = (1 - (1-w)^(1-a))/((1-a) w) */
    { 2, 1, { "1", AL }, { "2" },
      "(1 - (1 - " W ")^(1 - " AL "))/((1 - " AL ") " W ")", AL " != 1", 1 },
    /* 2F1(1, a; a+1; w) = a Phi(w, 1, a) */
    { 2, 1, { "1", AL }, { AL " + 1" },
      AL " Hrep`phi[" W ", 1, " AL "]",
      "!(IntegerQ[" AL "] && " AL " <= 0)", 1 },

    /* ---- 1F2 ------------------------------------------------------- */
    /* 1F2(1; 2, b; w) = (b-1)(0F1(; b-1; w) - 1)/w, the integral of 0F1 */
    { 1, 2, { "1" }, { "2", AL },
      "(" AL " - 1) (Gamma[" AL " - 1] Hrep`I[" AL " - 2, " W "] - 1)/" W,
      "!(IntegerQ[" AL "] && " AL " <= 1)", 1 },
    { 1, 2, { "1/2" }, { "3/2", "3/2" },
      "SinhIntegral[2 Sqrt[" W "]]/(2 Sqrt[" W "])", NULL, 0 },
    /* 1F2(a; a+1/2, 2a; w) = Gamma(a+1/2)^2 2^(2a-1) w^(1/2-a) I_(a-1/2)(sqrt w)^2 */
    { 1, 2, { AL }, { AL " + 1/2", "2 " AL },
      "Gamma[" AL " + 1/2]^2 2^(2 " AL " - 1) " W "^(1/2 - " AL ") "
      "BesselI[" AL " - 1/2, Sqrt[" W "]]^2",
      "!(IntegerQ[2 " AL "] && " AL " <= 0)", 1 },

    /* 1F2(1; 3/2, nu + 3/2; w) = Gamma(3/2) Gamma(nu + 3/2) w^(-(nu+1)/2) L_nu(2 sqrt w) */
    { 1, 2, { "1" }, { "3/2", AL " + 3/2" },
      "Gamma[3/2] Gamma[" AL " + 3/2] " W "^(-(" AL " + 1)/2) StruveL[" AL ", 2 Sqrt[" W "]]",
      "!(IntegerQ[2 " AL "] && " AL " <= -3/2)", 1 },
    /* 1F2(1/2; 1, 3/2; w) = I0(2 sqrt w) - Pi/2 (L0 I1 - L1 I0)(2 sqrt w): the integral of I0 */
    { 1, 2, { "1/2" }, { "1", "3/2" },
      "BesselI[0, 2 Sqrt[" W "]] - Pi/2 (StruveL[0, 2 Sqrt[" W "]] BesselI[1, 2 Sqrt[" W "]]"
      " - StruveL[1, 2 Sqrt[" W "]] BesselI[0, 2 Sqrt[" W "]])", NULL, 0 },

    /* ---- 0F3: Kelvin functions ------------------------------------- */
    /* 0F3(; 1/2, (nu+1)/2, (nu+2)/2; w) = Gamma(nu+1) (y/2)^-nu (I_nu(y) + J_nu(y))/2,
     * y = 4 w^(1/4): the even-in-k half of the Bessel series. Entire in w,
     * so any fourth root may stand for w^(1/4). At w = -x^4/256 it is
     * Gamma(nu+1) (x/2)^-nu ber_nu(x)-type: ber_0(x) = 0F3(; 1/2, 1/2, 1; -x^4/256),
     * bei_0(x) = (x^2/4) 0F3(; 1, 3/2, 3/2; -x^4/256), one lattice. The
     * answer is named by Hrep`kelvin. */
    { 0, 3, { 0 }, { "1/2", "(" AL " + 1)/2", "(" AL " + 2)/2" },
      "Gamma[" AL " + 1] (2 " W "^(1/4))^(-" AL ") (BesselI[" AL ", 4 " W "^(1/4)]"
      " + BesselJ[" AL ", 4 " W "^(1/4)])/2",
      "!(IntegerQ[" AL "] && " AL " <= -1)", 1 },
    /* 0F3(; nu+1, (nu+1)/2, (nu+2)/2; -x^4/64) = Gamma(nu+1)^2 (x/2)^(-2 nu) J_nu(x) I_nu(x),
     * written at x = 2 Sqrt[2] (-1)^(1/4) w^(1/4) (x^4 = -64 w). For nu = 0
     * and w = u > 0 the product is ber_0^2 + bei_0^2 of 2 Sqrt[2] u^(1/4). */
    { 0, 3, { 0 }, { AL " + 1", "(" AL " + 1)/2", "(" AL " + 2)/2" },
      "Gamma[" AL " + 1]^2 (Sqrt[2] (-1)^(1/4) " W "^(1/4))^(-2 " AL ")"
      " BesselJ[" AL ", 2 Sqrt[2] (-1)^(1/4) " W "^(1/4)]"
      " BesselI[" AL ", 2 Sqrt[2] (-1)^(1/4) " W "^(1/4)]",
      "!(IntegerQ[" AL "] && " AL " <= -1)", 1 },

    /* ---- 3F2 ------------------------------------------------------- */
    /* Clausen: 3F2(1, 1, 1; 3/2, 2; w) = 2F1(1/2, 1/2; 3/2; w)^2 */
    { 3, 2, { "1", "1", "1" }, { "3/2", "2" }, "ArcSin[Sqrt[" W "]]^2/" W, NULL, 0 },
};

const HrCert* hr_certificates(int* n) {
    *n = (int)(sizeof CERTS / sizeof CERTS[0]);
    return CERTS;
}

/* ---- Meijer G certificates (PBM vol. 3 sec. 8.4, the Roach`GForm table
 *      of src/internal/RoachIntegrate.m read backwards) ---------------- */
static const HrGCert GCERTS[] = {
    /* G^{1,0}_{0,1}(w | ; b) = w^b e^-w */
    { 1, 0, 0, 1, { 0 }, { AL }, W "^" AL " E^(-" W ")", NULL, 1 },
    /* G^{1,0}_{0,2}(w | ; b1 ; b2) = w^((b1+b2)/2) J_(b1-b2)(2 sqrt w) */
    { 1, 0, 0, 2, { 0 }, { AL, BE },
      W "^((" AL " + " BE ")/2) BesselJ[" AL " - " BE ", 2 Sqrt[" W "]]", NULL, 2 },
    /* G^{2,0}_{0,2}(w | ; b1, b2) = 2 w^((b1+b2)/2) K_(b1-b2)(2 sqrt w) */
    { 2, 0, 0, 2, { 0 }, { AL, BE },
      "2 " W "^((" AL " + " BE ")/2) BesselK[" AL " - " BE ", 2 Sqrt[" W "]]", NULL, 2 },
    /* G^{1,1}_{1,1}(w | a ; b) = Gamma(1 - a + b) w^b (1 + w)^(a - b - 1) */
    { 1, 1, 1, 1, { AL }, { BE },
      "Gamma[1 - " AL " + " BE "] " W "^" BE " (1 + " W ")^(" AL " - " BE " - 1)",
      "!(IntegerQ[" AL " - " BE "] && " AL " - " BE " >= 1)", 2 },
    /* G^{1,2}_{2,2}(w | 1, 1 ; 1 ; 0) = Log(1 + w) */
    { 1, 2, 2, 2, { "1", "1" }, { "1", "0" }, "Log[1 + " W "]", NULL, 0 },
    /* G^{1,2}_{2,2}(w | 1/2, 1 ; 1/2 ; 0) = 2 ArcTan(sqrt w) */
    { 1, 2, 2, 2, { "1/2", "1" }, { "1/2", "0" }, "2 ArcTan[Sqrt[" W "]]", NULL, 0 },
    /* G^{1,2}_{2,2}(w | 1/2, 1/2 ; 0 ; 0) = 2 K(-w) */
    { 1, 2, 2, 2, { "1/2", "1/2" }, { "0", "0" }, "2 EllipticK[-" W "]", NULL, 0 },
    /* G^{2,0}_{1,2}(w | ; 1 ; a, 0) = Gamma(a, w) */
    { 2, 0, 1, 2, { "1" }, { AL, "0" }, "Gamma[" AL ", " W "]", NULL, 1 },
    /* G^{2,0}_{1,2}(w | ; 1 ; 0, 1/2) = sqrt(Pi) Erfc(sqrt w) */
    { 2, 0, 1, 2, { "1" }, { "0", "1/2" }, "Sqrt[Pi] Erfc[Sqrt[" W "]]", NULL, 0 },
    /* G^{2,0}_{1,3}(w | ; -(nu+1)/2 ; nu/2, -nu/2 ; -(nu+1)/2) = Y_nu(2 sqrt w) */
    { 2, 0, 1, 3, { "-(" AL " + 1)/2" }, { AL "/2", "-" AL "/2", "-(" AL " + 1)/2" },
      "BesselY[" AL ", 2 Sqrt[" W "]]", NULL, 1 },
    /* G^{1,1}_{1,3}(w | (nu+1)/2 ; (nu+1)/2 ; -nu/2, nu/2) = H_nu(2 sqrt w) */
    { 1, 1, 1, 3, { "(" AL " + 1)/2" }, { "(" AL " + 1)/2", "-" AL "/2", AL "/2" },
      "StruveH[" AL ", 2 Sqrt[" W "]]", NULL, 1 },
    /* G^{1,1}_{1,3}(w | 1 ; 1/2 ; 0, 0) = (2/sqrt Pi) Si(2 sqrt w) */
    { 1, 1, 1, 3, { "1" }, { "1/2", "0", "0" }, "2 SinIntegral[2 Sqrt[" W "]]/Sqrt[Pi]", NULL, 0 },
    /* G^{2,0}_{1,3}(w | ; 1 ; 0, 0 ; 1/2) = -(2/sqrt Pi) Ci(2 sqrt w) */
    { 2, 0, 1, 3, { "1" }, { "0", "0", "1/2" }, "-2 CosIntegral[2 Sqrt[" W "]]/Sqrt[Pi]", NULL, 0 },
    /* Kelvin functions of the second kind, by their Mellin transforms
     * M[ker_0](s) = 2^(s-2) Gamma(s/2)^2 cos(Pi s/4), M[kei_0](s) = -2^(s-2) Gamma(s/2)^2 sin(Pi s/4)
     * and Gamma duplication, at x = 4 w^(1/4):
     * G^{3,0}_{0,4}(w | ; 0, 0, 1/2 ; 1/2) = 4 ker_0(4 w^(1/4)) */
    { 3, 0, 0, 4, { 0 }, { "0", "0", "1/2", "1/2" }, "4 KelvinKer[0, 4 " W "^(1/4)]", NULL, 0 },
    /* G^{3,0}_{0,4}(w | ; 0, 1/2, 1/2 ; 0) = -4 kei_0(4 w^(1/4)) */
    { 3, 0, 0, 4, { 0 }, { "0", "1/2", "1/2", "0" }, "-4 KelvinKei[0, 4 " W "^(1/4)]", NULL, 0 },
};

const HrGCert* hr_gcertificates(int* n) {
    *n = (int)(sizeof GCERTS / sizeof GCERTS[0]);
    return GCERTS;
}
